INSERT INTO ar_acq_audio_segment (id, audio_id, seq, start_sec, end_sec, text_ar, text_en, is_reviewed, meta_json) VALUES ('AUD:NTN:AR-163:1:27', 'AUD:NTN:AR-163:1', 27, 214.52, 221.8, 'ذاك جمالنا، يسمو يتعالى', 'that is our beauty: it rises, it soars.', 1, '{"w": [[214.52, 215.3], [215.3, 216.28], [216.28, 217.76], [217.76, 221.8]], "unit": "ARTX:AR-163:1", "anchored": true, "stanza": 7}');
