UPDATE ar_acquisition_ref SET status = 'live', title_ar = 'لا تبك', title_en = 'Don''t Cry', author = 'حمزة نمرة', level = 'A2', verse_form = 'song', meta_json = json_set(json_remove(meta_json, '$.archived'), '$.shape', 'lyrics', '$.singer_en', 'Hamza Namira') WHERE id = 'ACQ:NTN:AR-164';
UPDATE ar_text_unit SET text_ar = '[موسيقى]

لا تبكي، فأحزان الصغر
تمضي كالحلم مع الفجر
وقريبًا تكبر يا ولدي
وتريد الدمع فلا يجري

إن سهرت أمطار معنا
أو غطى البرد شوارعنا
فالدفء يعمر أضلعنا
ولهيب الأرض بنا يسري

وشموس رفاقك آتية
وستشرق من غضب الفقر

لا تبكي، لا يا ولدي
لا تبكي، لا يا ولدي
لا تبكي، لا يا ولدي

[موسيقى]

ولدي، قد أرمى خلف الجدران
وتحن لحبي وحناني
فانظر في قلبك ستراني
لن يقوى القيد على الفكر

وإذا ما الدهر بنا دارا
ومضيت إلى حيث أوارى
أكمل من بعدي المشوار
لا تخلف ميعاد الفجر

لن يسقي دمع أشجارك
لا تخشى النار من الجمر

لا تبكي، لا يا ولدي
لا تبكي، لا يا ولدي
لا تبكي، لا يا ولدي

سأضمك والصدر جريح
وسأعشق والقلب ذبيح
مهما عصفت ضد الريح
لن أحني في يوم ظهري

لا تبكي، لا يا ولدي
لا تبكي، لا يا ولدي
لا تبكي، لا يا ولدي

[موسيقى]', title_ar = 'لا تبك', word_count = 141, char_count = 710, status = 'live', meta_json = json_set(meta_json, '$.stanzas', json('[{"kind": "music", "lines": []}, {"kind": "verse", "lines": [{"ar": "لا تبكي، فأحزان الصغر", "en": "Don''t cry — the sorrows of childhood"}, {"ar": "تمضي كالحلم مع الفجر", "en": "pass like a dream at dawn,"}, {"ar": "وقريبًا تكبر يا ولدي", "en": "and soon you will grow up, my son,"}, {"ar": "وتريد الدمع فلا يجري", "en": "and want tears, and they will not flow."}]}, {"kind": "verse", "lines": [{"ar": "إن سهرت أمطار معنا", "en": "If the rains stay up the night with us,"}, {"ar": "أو غطى البرد شوارعنا", "en": "or the cold covers our streets,"}, {"ar": "فالدفء يعمر أضلعنا", "en": "warmth fills our ribs,"}, {"ar": "ولهيب الأرض بنا يسري", "en": "and the fire of the land runs through us."}]}, {"kind": "verse", "lines": [{"ar": "وشموس رفاقك آتية", "en": "The suns of your companions are coming,"}, {"ar": "وستشرق من غضب الفقر", "en": "and they will rise from the anger of the poor."}]}, {"kind": "chorus", "lines": [{"ar": "لا تبكي، لا يا ولدي", "en": "Don''t cry — no, my son,"}, {"ar": "لا تبكي، لا يا ولدي", "en": "don''t cry — no, my son,"}, {"ar": "لا تبكي، لا يا ولدي", "en": "don''t cry — no, my son."}]}, {"kind": "music", "lines": []}, {"kind": "verse", "lines": [{"ar": "ولدي، قد أرمى خلف الجدران", "en": "My son, I may be thrown behind walls,"}, {"ar": "وتحن لحبي وحناني", "en": "and you will long for my love and my tenderness;"}, {"ar": "فانظر في قلبك ستراني", "en": "look into your heart and you will see me —"}, {"ar": "لن يقوى القيد على الفكر", "en": "chains have no power over thought."}]}, {"kind": "verse", "lines": [{"ar": "وإذا ما الدهر بنا دارا", "en": "And if time turns against us,"}, {"ar": "ومضيت إلى حيث أوارى", "en": "and I go where I am laid to rest,"}, {"ar": "أكمل من بعدي المشوار", "en": "carry on the journey after me;"}, {"ar": "لا تخلف ميعاد الفجر", "en": "do not miss your meeting with the dawn."}]}, {"kind": "verse", "lines": [{"ar": "لن يسقي دمع أشجارك", "en": "Tears will not water your trees;"}, {"ar": "لا تخشى النار من الجمر", "en": "do not fear the fire from the embers."}]}, {"kind": "chorus", "lines": [{"ar": "لا تبكي، لا يا ولدي", "en": "Don''t cry — no, my son,"}, {"ar": "لا تبكي، لا يا ولدي", "en": "don''t cry — no, my son,"}, {"ar": "لا تبكي، لا يا ولدي", "en": "don''t cry — no, my son."}]}, {"kind": "verse", "lines": [{"ar": "سأضمك والصدر جريح", "en": "I will hold you, though my chest is wounded,"}, {"ar": "وسأعشق والقلب ذبيح", "en": "and I will love, though my heart is slain;"}, {"ar": "مهما عصفت ضد الريح", "en": "however hard the wind blows against me,"}, {"ar": "لن أحني في يوم ظهري", "en": "I will never, on any day, bend my back."}]}, {"kind": "chorus", "lines": [{"ar": "لا تبكي، لا يا ولدي", "en": "Don''t cry — no, my son,"}, {"ar": "لا تبكي، لا يا ولدي", "en": "don''t cry — no, my son,"}, {"ar": "لا تبكي، لا يا ولدي", "en": "don''t cry — no, my son."}]}, {"kind": "music", "lines": []}]')) WHERE id = 'ARTX:AR-164:1';
