INSERT INTO ar_acq_audio_segment (id, audio_id, seq, start_sec, end_sec, text_ar, text_en, is_reviewed, meta_json) VALUES ('AUD:NTN:AR-164:1:28', 'AUD:NTN:AR-164:1', 28, 189.58, 192.91, 'وسأعشق والقلب ذبيح', 'and I will love, though my heart is slain;', 1, '{"w": [[189.58, 190.98], [190.98, 191.88], [191.88, 192.91]], "unit": "ARTX:AR-164:1", "anchored": true, "stanza": 10}');
INSERT INTO ar_acq_audio_segment (id, audio_id, seq, start_sec, end_sec, text_ar, text_en, is_reviewed, meta_json) VALUES ('AUD:NTN:AR-164:1:29', 'AUD:NTN:AR-164:1', 29, 193.94, 200.24, 'مهما عصفت ضد الريح', 'however hard the wind blows against me,', 1, '{"w": [[193.94, 196.28], [196.28, 197.22], [197.22, 197.56], [197.56, 200.24]], "unit": "ARTX:AR-164:1", "anchored": true, "stanza": 10}');
